{
  "technical_and_design_decisions": [
    "For U1: In Java, use a factory pattern to create a new contract instance per transaction for thread safety; in Node.js, ensure transactional context is consistently passed as the first parameter.",
    "For U5: Implement a new read-only chaincode method (e.g., 'query') that only allows Get operations, and enforce channel Reader permission for that method.",
    "For U6: Add a new configuration option 'peer.externalEndpoint' to override the external endpoint used in gossip and service discovery, eliminating the need for DNS.",
    "For U7: Add a new HTTP GET endpoint '/version' to the operations service that returns the peer/orderer version string.",
    "For U8: Rewrite Go sample chaincode to follow idiomatic Go conventions, including proper error handling, naming, and comments."
  ],
  "assumptions": [
    "U2 and U3 are identical user stories; only one implementation task is required.",
    "The developer has full access to the Hyperledger Fabric repository and existing build/test infrastructure.",
    "All unit tests are run as part of development; integration tests are performed separately.",
    "Code review is performed by the same developer (self-review) and accounted as a separate activity.",
    "Existing documentation will be updated accordingly for new features.",
    "For U4, the Kafka health checks are available in the master branch and can be cleanly cherry-picked to the 1.4 LTS branch."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Implement transactional context for contract developers (U1)",
      "activity_description": "Design and implement provision of transactional context to chaincode methods for Node.js and Java, including per-transaction instance creation for Java.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A2",
      "activity_name": "Move protos/utils to protoutils (U2/U3)",
      "activity_description": "Refactor the protos package by moving utilities from protos/utils to a new package protoutils, updating all imports and build configurations.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A3",
      "activity_name": "Backport Kafka health checks to Fabric 1.4 LTS (U4)",
      "activity_description": "Identify and cherry-pick commits from master that implement Kafka health checks, adapt for the 1.4 LTS branch, and verify.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A4",
      "activity_name": "Implement access control for read-only chaincode invocation (U5)",
      "activity_description": "Design and implement a read-only chaincode method (query) that only allows Get operations, modify permission checking to allow channel Readers to invoke it.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A5",
      "activity_name": "Add explicit external endpoint for peers in service discovery (U6)",
      "activity_description": "Add configuration option for external endpoint, modify gossip and service discovery to use it instead of relying on DNS.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A6",
      "activity_name": "Add version endpoint to operations service (U7)",
      "activity_description": "Add a new /version HTTP endpoint to the operations service that returns the peer/orderer version.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A7",
      "activity_name": "Improve Go sample chaincode to be idiomatic (U8)",
      "activity_description": "Rewrite the Go sample chaincode to follow idiomatic Go patterns, proper error handling, and naming conventions.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A8",
      "activity_name": "Integration and system testing",
      "activity_description": "Run full integration tests on all changes combined, fix any issues found.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A9",
      "activity_name": "Code review",
      "activity_description": "Review all code changes for correctness, style, and adherence to conventions.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A10",
      "activity_name": "Documentation update",
      "activity_description": "Update user documentation for new features: read-only invocation, external endpoint, version endpoint, and context changes.",
      "most_likely_effort": 2
    }
  ],
  "reported_total": {
    "most_likely_effort": 22
  }
}

